@@ -18,3 +18,14 @@ func (c *Cache) Put(key, value string) {
 	defer c.mu.Unlock()
 	c.items[key] = value
 }
+
+// Get returns the value stored under key and whether it exists.
+func (c *Cache) Get(key string) (string, bool) {
+	c.mu.Lock()
+	v, ok := c.items[key]
+	if !ok {
+		return "", false
+	}
+	c.mu.Unlock()
+	return v, true
+}
